<h2>Estimate material length on a roll</h2><p class="lead">Calculate roll length from outside diameter, core diameter and material thickness.</p><div class="notice">Measure outside diameter and core diameter at the same location and use actual material caliper including adhesive/liner layers where relevant.</div><div class="form-grid"><div class="field"><label for="od">Outside roll diameter (mm)</label><input id="od" type="number" value="300" min="0.1" step="any"></div><div class="field"><label for="idiam">Core outside diameter (mm)</label><input id="idiam" type="number" value="76" min="0" step="any"></div><div class="field"><label for="th">Material thickness (microns)</label><input id="th" type="number" value="100" min="0.01" step="any"></div><div class="field"><label for="width">Web width (mm)</label><input id="width" type="number" value="1000" min="0.1" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Estimated roll length</span><strong id="length">—</strong></div><div class="metric"><span>Material area</span><strong id="area">—</strong></div><div class="metric"><span>Approx. radial layers</span><strong id="turns">—</strong></div><div class="metric"><span>OD / core ratio</span><strong id="ratio">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('length').textContent='—';$('area').textContent='—';$('turns').textContent='—';$('ratio').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const D=num('od'),d=num('idiam'),um=num('th'),w=num('width');const t=um/1000;if(!(D>0&&d>=0&&D>d&&t>0&&w>0))throw 0;const L=Math.PI*(D*D-d*d)/(4*t),area=(L/1000)*(w/1000),layers=(D-d)/(2*t);$('length').textContent=fmt(L/1000,2)+' m';$('area').textContent=fmt(area,2)+' m²';$('turns').textContent=fmt(layers,0);$('ratio').textContent=fmt(D/Math.max(d,0.0001),2)+'×';$('note').textContent='The geometric formula assumes uniform thickness and tight, gap-free winding. Real roll length varies with compression, air, tension and thickness tolerance.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
